    private void capture(){if(rendering||model==null||title==null||description==null||region==null)return;model.changed(title.getText()==null?"":title.getText().toString(),description.getText()==null?"":description.getText().toString(),Math.max(0,region.getSelectedItemPosition()));}
    private boolean validate(boolean complete){titleLayout.setError(null);descriptionLayout.setError(null);Map<String,Object> f=model.fields();if(!text(f.get("title"),complete?5:0,80,320)){titleLayout.setError(getString(R.string.listing_invalid));title.requestFocus();return false;}if(!text(f.get("description"),0,2000,8000)){descriptionLayout.setError(getString(R.string.listing_invalid));description.requestFocus();return false;}return true;}
    private void confirm(int res,Runnable run){dialog=new MaterialAlertDialogBuilder(this).setMessage(res).setNegativeButton(R.string.listing_cancel,null).setPositiveButton(R.string.listing_confirm,(d,w)->run.run()).show();}
    private void preview(){if(!validate(false))return;Map<String,Object> f=model.fields();String region=getResources().getStringArray(R.array.listing_regions)[model.region];dialog=new MaterialAlertDialogBuilder(this).setTitle(R.string.listing_preview).setMessage(getString(R.string.listing_candidate,f.get("title"),f.get("description"),region)).setPositiveButton(android.R.string.ok,null).show();}
